import type { Api, AssistantMessage, Context, Model, Usage } from "@earendil-works/pi-ai";
import { uuidv7 } from "@earendil-works/pi-ai";
import type { ExtensionContext } from "@earendil-works/pi-coding-agent";

import {
    MIN_CHECKPOINT_SECTIONS,
    SERIALIZATION_SYSTEM_PROMPT,
    checkpointSectionCount,
} from "./prompt";

/**
 * The two summarization strategies, and the shape their caller cascades over.
 *
 * Both are allowed to fail: a provider that ignores `toolChoice`, a summary that comes back empty, a
 * request that turns out too large. Each failure is a value, never an exception, because the handler that
 * owns the cascade must be able to fall through to pi's own compaction rather than abort it.
 */

export type SummarizationStrategy = "native" | "serialized";

/**
 * What one strategy call returns: usable summary text, or the reason it is unusable.
 *
 * `usage` is reported on both arms — a response that ignored `tool_choice` still cost tokens, and that is
 * the evidence the trace wants.
 */
export type SummarizationAttemptResult =
    | { ok: true; strategy: SummarizationStrategy; text: string; usage: Usage }
    | { ok: false; strategy: SummarizationStrategy; detail: string; usage?: Usage };

type ModelRegistry = ExtensionContext["modelRegistry"];

export interface SummarizationCall {
    registry: ModelRegistry;
    model: Model<Api>;
    maxTokens: number;
    signal?: AbortSignal;
    /** Session id for provider affinity. Omitted on one-off requests that can never reuse a cache. */
    sessionId?: string;
    /**
     * Inspects the assembled request body before it is sent. Returning undefined leaves it unchanged, which
     * is all the compaction trace ever does; used to compare our rebuilt prefix against the parent's.
     */
    onPayload?: (payload: unknown) => void;
}

function responseText(response: AssistantMessage): string {
    return response.content
        .filter((block): block is { type: "text"; text: string } => block.type === "text")
        .map((block) => block.text)
        .join("");
}

function attemptedToolCall(response: AssistantMessage): string | undefined {
    const call = response.content.find((block) => block.type === "toolCall");
    if (!call || call.type !== "toolCall") {
        return undefined;
    }
    return call.name;
}

/**
 * Turn a provider response into summary text, rejecting anything that tried to keep working.
 *
 * We sit outside the agent loop, so a tool call in this response would never execute. That is not a
 * failure to paper over: a model that ignored `toolChoice: "none"` is a model that will also ignore the
 * rest of the directive, so the caller should cascade to the strategy that sends no tools at all.
 */
export function evaluateSummarizationResponse(
    response: AssistantMessage,
    strategy: SummarizationStrategy,
): SummarizationAttemptResult {
    if (response.stopReason === "error" || response.stopReason === "aborted") {
        return {
            ok: false,
            strategy,
            usage: response.usage,
            detail:
                response.errorMessage ?? `summarization ${strategy} call ${response.stopReason}`,
        };
    }
    const tool = attemptedToolCall(response);
    if (tool) {
        return {
            ok: false,
            strategy,
            usage: response.usage,
            detail: `model called "${tool}" instead of summarizing; this provider does not honor tool_choice none`,
        };
    }
    const text = responseText(response).trim();
    if (!text) {
        return {
            ok: false,
            strategy,
            usage: response.usage,
            detail: "summarization returned an empty summary",
        };
    }

    // A reply that carries the demanded sections is the only thing the rest of the pipeline can use: the
    // headings are what `sections.ts` reads, so this is a usability check rather than a style one. It exists
    // because a real 2026-09-05 run answered with 35 tokens of "I don't have any prior thinking to
    // reproduce" - non-empty, fluent, and useless as the session's memory - and was accepted on that basis.
    // Rejecting cascades to the serialized strategy, the rung that can still produce something.
    const sections = checkpointSectionCount(text);
    if (sections < MIN_CHECKPOINT_SECTIONS) {
        return {
            ok: false,
            strategy,
            usage: response.usage,
            detail:
                `summarization ${strategy} answer carried ${String(sections)} of ` +
                `${String(MIN_CHECKPOINT_SECTIONS)} required sections: ${text.slice(0, 120)}`,
        };
    }

    return { ok: true, strategy, text, usage: response.usage };
}

async function callForSummary(
    call: SummarizationCall,
    context: Context,
    options: Record<string, unknown>,
    strategy: SummarizationStrategy,
): Promise<SummarizationAttemptResult> {
    try {
        const response = await call.registry.complete(call.model, context, options);
        return evaluateSummarizationResponse(response, strategy);
    } catch (error) {
        return {
            ok: false,
            strategy,
            detail: error instanceof Error ? error.message : String(error),
        };
    }
}

/** Continue the live conversation with a summarize instruction and no usable tools. */
export async function summarizeNatively(
    call: SummarizationCall,
    context: Context,
): Promise<SummarizationAttemptResult> {
    return callForSummary(
        call,
        context,
        {
            maxTokens: call.maxTokens,
            signal: call.signal,
            ...(call.onPayload
                ? {
                      onPayload: (payload: unknown) => {
                          call.onPayload?.(payload);
                          return undefined;
                      },
                  }
                : {}),
            // The field every capable provider understands; the instruction message is the backstop for
            // the ones that do not, and a tool call in the response cascades us off this path.
            toolChoice: "none",
            ...(call.sessionId ? { sessionId: call.sessionId } : {}),
        },
        "native",
    );
}

export interface SerializedTranscriptInput {
    /** The minimized transcript, built by the caller so the trace can see the same text that is sent. */
    conversationText: string;
    /** The complete request text: transcript, prior summary, format, and focus. */
    requestText: string;
}

/** One-off standalone request over a minimized transcript: no cache prefix to protect, no tools to forbid. */
export async function summarizeSerializedTranscript(
    call: SummarizationCall,
    input: SerializedTranscriptInput,
): Promise<SummarizationAttemptResult> {
    const context: Context = {
        systemPrompt: SERIALIZATION_SYSTEM_PROMPT,
        messages: [
            {
                role: "user",
                content: [{ type: "text", text: input.requestText }],
                timestamp: Date.now(),
            },
        ],
    };
    return callForSummary(
        call,
        context,
        {
            maxTokens: call.maxTokens,
            signal: call.signal,
            cacheRetention: "none",
            sessionId: uuidv7(),
        },
        "serialized",
    );
}

import { SessionManager, type SessionEntry } from "@earendil-works/pi-coding-agent";

/**
 * The stage-1 transcript: pi's own context entries, truncated where compaction is about to cut.
 *
 * Stage 1 asks the model to summarize the span it is about to lose, using the real message objects rather
 * than a re-serialization of them. Building that request by slicing converted messages means guessing which
 * entries produce which messages (custom entries, compaction boundaries, `excludeFromContext` bash runs,
 * branch summaries), so instead the entries are copied into an in-memory transcript and pi's
 * `buildSessionContext()` resolves it. The result is a strict prefix of what the parent already sent, which
 * is the whole point: the retained tail is not re-read, and the provider's cached prefix still covers it.
 *
 * pi 0.84 exposes no public append for `branch_summary` entries (its own comment references an
 * `appendBranchSummary()` that does not exist), so those are reported as skipped rather than faked. Stage 2's
 * minimized transcript is built from `preparation.messagesToSummarize`, which still contains them, so the
 * summarizer does not lose the branch context — only stage 1's view of it is narrower.
 */

/** Entry types an in-memory transcript can be rebuilt from through a public append. */
const COPYABLE_TYPES = new Set([
    "message",
    "compaction",
    "custom_message",
    "custom",
    "model_change",
    "thinking_level_change",
]);

export interface SpanSession {
    sessionManager: SessionManager;
    copiedEntries: number;
    /** Counts per entry type that could not be copied, newest reason for a narrower stage-1 context. */
    skippedEntries: Record<string, number>;
}

/**
 * The context entries before the cut point.
 *
 * `firstKeptEntryId` is where pi's retained tail starts, so everything before it is what stage 1 should see
 * and everything from it onward is what stage 1 must not re-read.
 */
export function spanContextEntries(
    contextEntries: SessionEntry[],
    firstKeptEntryId: string,
): SessionEntry[] {
    const cut = contextEntries.findIndex((entry) => entry.id === firstKeptEntryId);
    if (cut < 0) {
        return contextEntries;
    }
    return contextEntries.slice(0, cut);
}

export function buildSpanSession(entries: SessionEntry[], cwd: string): SpanSession {
    const sessionManager = SessionManager.inMemory(cwd);
    const skippedEntries: Record<string, number> = {};
    let copiedEntries = 0;
    let firstCopiedId: string | undefined;

    for (const entry of entries) {
        if (!COPYABLE_TYPES.has(entry.type)) {
            skippedEntries[entry.type] = (skippedEntries[entry.type] ?? 0) + 1;
            continue;
        }
        const appended = appendSpanEntry(sessionManager, entry, firstCopiedId);
        if (appended === undefined) {
            skippedEntries[entry.type] = (skippedEntries[entry.type] ?? 0) + 1;
            continue;
        }
        firstCopiedId ??= appended;
        copiedEntries += 1;
    }

    return { sessionManager, copiedEntries, skippedEntries };
}

/**
 * Copy one entry, returning its id in the new transcript, or undefined when it could not be copied.
 *
 * `firstCopiedId` matters for compaction entries: the parent's `firstKeptEntryId` names an entry this
 * transcript never saw, and an unmatched id makes pi keep everything from the compaction entry onward while
 * *also* keeping everything before it — which is exactly the resolved context stage 1 is meant to read. When
 * the compaction entry is itself first, nothing precedes it to preserve, so the original id is harmless.
 */
function appendSpanEntry(
    sessionManager: SessionManager,
    entry: SessionEntry,
    firstCopiedId: string | undefined,
): string | undefined {
    switch (entry.type) {
        case "message": {
            const message = entry.message;
            // Summary roles live in their own entry types; a stray message-shaped one is refused rather
            // than silently dropped, because `appendMessage` throws on them.
            if (message.role === "compactionSummary" || message.role === "branchSummary") {
                return undefined;
            }
            return sessionManager.appendMessage(message);
        }
        case "compaction":
            return sessionManager.appendCompaction(
                entry.summary,
                firstCopiedId ?? entry.firstKeptEntryId,
                entry.tokensBefore,
                entry.details,
                entry.fromHook,
                entry.usage,
            );
        case "custom_message":
            return sessionManager.appendCustomMessageEntry(
                entry.customType,
                entry.content,
                entry.display,
                entry.details,
            );
        case "custom":
            return sessionManager.appendCustomEntry(entry.customType, entry.data);
        case "model_change":
            return sessionManager.appendModelChange(entry.provider, entry.modelId);
        case "thinking_level_change":
            return sessionManager.appendThinkingLevelChange(entry.thinkingLevel);
        default:
            return undefined;
    }
}

/** Sum of the entries stage 1 could not see because no public append exists for them. */
export function skippedEntryCount(skipped: Record<string, number>): number {
    return Object.values(skipped).reduce((total, count) => total + count, 0);
}

/**
 * Payload fingerprinting for the compaction trace.
 *
 * Provider usage numbers cannot answer the prefix question on their own. `cacheRead: 0` is reported both when
 * the request body diverged at the first token and when the endpoint simply will not serve a cache entry to a
 * request that extends or rewinds the conversation. So a request is reduced to hashes and counts here, and
 * `chain.ts` retains those per turn: our rebuilt body is then matched against what pi actually sent, at the
 * exact depth where the two stop agreeing.
 *
 * Payloads are shaped per API (`system` string for Anthropic-style, a system/developer message for
 * OpenAI-style; `tools` with `input_schema` or `parameters`), so nothing here assumes one: fields are read
 * best-effort and anything unrecognized is compared by hash, which is exactly what a cache key does.
 */

import type { ChainShape } from "./chain";

/** A short head of each side of a divergence, so the report says *what* differs, not just where. */
const EXCERPT_CHARS = 320;

export interface PayloadFingerprint {
    /** Top-level body keys, sorted: catches `prompt_cache_key` or marker differences. */
    keys: string[];
    model: string;
    system: string;
    systemChars: number;
    toolNames: string[];
    toolsHash: string;
    /** One hash per message in body order, including role-only entries. */
    messageHashes: string[];
    messageRoles: string[];
}

function asRecord(value: unknown): Record<string, unknown> {
    return value && typeof value === "object" ? (value as Record<string, unknown>) : {};
}

function hash(value: unknown): string {
    const text = typeof value === "string" ? value : safeStringify(value);
    // FNV-1a: collisions are irrelevant here, this is a dev diagnostic comparing two known bodies.
    let result = 0x811c9dc5;
    for (let index = 0; index < text.length; index += 1) {
        result ^= text.charCodeAt(index);
        result = Math.imul(result, 0x01000193);
    }
    return (result >>> 0).toString(16).padStart(8, "0");
}

function safeStringify(value: unknown): string {
    try {
        return JSON.stringify(value) ?? "";
    } catch {
        return String(value);
    }
}

function excerpt(value: unknown): string {
    const text = typeof value === "string" ? value : safeStringify(value);
    return text.length <= EXCERPT_CHARS ? text : `${text.slice(0, EXCERPT_CHARS)}…`;
}

const SYSTEM_ROLES = new Set(["system", "developer"]);

/** Raw text, not an excerpt: the hash over it must cover drift past what the record prints. */
function systemText(payload: Record<string, unknown>): { text: string; chars: number } {
    const direct = payload.system;
    if (typeof direct === "string") {
        return { text: direct, chars: direct.length };
    }
    if (direct !== undefined && direct !== null) {
        const text = safeStringify(direct);
        return { text, chars: text.length };
    }
    const messages = Array.isArray(payload.messages) ? payload.messages : [];
    for (const entry of messages) {
        const message = asRecord(entry);
        if (typeof message.role === "string" && SYSTEM_ROLES.has(message.role)) {
            const text =
                typeof message.content === "string"
                    ? message.content
                    : safeStringify(message.content);
            return { text, chars: text.length };
        }
    }
    return { text: "", chars: 0 };
}

function toolsOf(payload: Record<string, unknown>): unknown[] {
    return Array.isArray(payload.tools) ? payload.tools : [];
}

function nestedName(value: unknown): string | undefined {
    const record = asRecord(value);
    return typeof record.name === "string" ? record.name : undefined;
}

/** Tool entries are `{ name }` for Anthropic-style bodies and `{ function: { name } }` for OpenAI-style. */
function toolName(tool: unknown): string {
    return nestedName(tool) ?? nestedName(asRecord(tool).function) ?? "<unnamed>";
